class Document {
  #parts = [];                    // parts: private, never handed out mutably
  #file;
  constructor(path) { this.#file = fs.openSync(path, "w+"); }
  add(text) { this.#parts.push(openParagraph(text)); return this; }
  [Symbol.dispose]() {            // the only release path
    for (const p of this.#parts) p[Symbol.dispose]();
    fs.closeSync(this.#file);
  }
}
